      ...activeLeaderModifiers(battle,fighter.id)]
      .filter(mod=>mod.stat===stat&&mod.operation==="flat")
      .reduce((total,mod)=>total+mod.value,0);
    const effective=Math.max(stat==="speed"?1:0,base+addition);
