    if(!w||w.ownerId===actor.id)return; // Sava's casting turn is not a chain link.
    const owner=battle.fighters.find(f=>f.id===w.ownerId);
    if(!owner||owner.hp<=0){battle.coordinatedWindow=null;return;}
